import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"14、【大有】 乾下离上","description":"周易口诀义 - 14、【大有】 乾下离上","frontmatter":{"title":"14、【大有】 乾下离上","description":"周易口诀义 - 14、【大有】 乾下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/016.md","filePath":"zh/classics/koujueyi/016.md"}'),r={name:"zh/classics/koujueyi/016.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_14、【大有】-乾下离上" tabindex="-1">14、【大有】 乾下离上 <a class="header-anchor" href="#_14、【大有】-乾下离上" aria-label="Permalink to “14、【大有】 乾下离上”">​</a></h1><p>彖曰：「大有」，柔得尊位，大中而上下应之，曰「大有」。其德刚健而文明，应乎天而时行，是以「元亨」。</p><p>象曰：火在天上，「大有」。君子以遏恶扬善，顺天休命。</p><p>初九，无交害，匪咎，艰则无咎。</p><p>象曰：大有初九，无交害也。</p><p>九二，大车以载，有攸往，无咎。</p><p>象曰：「大车以载」，积中不败也。</p><p>九三，公用亨于天子，小人弗克。</p><p>象曰：「公用亨于天子」，小人害也。</p><p>九四，匪其彭，无咎。象曰：「匪其彭无咎」，明辨晳也。</p><p>六五，厥孚交如威如，吉。</p><p>象曰：「厥孚交如」，信以发志也。威如之吉，易而无备也。</p><p>上九，自天祐之，吉无不利。</p><p>象曰：大有上吉，「自天祐」也。</p><p>解读</p><p>大有元亨者，柔处尊位，不拒于物，群阳并应，大为所有，故称「大有」。故老子云：「江海所以能为百谷王者，以其善下也。」元亨者，能包容万物，则大得亨通也。</p><p>象曰「火在天上，大有，君子以遏恶扬善，顺天休命」者，火是日，如日在天上，无所不照，无远不烛，是「大有」之象也。君子当须遏匿人之过恶，称扬人之德善，又须顺天之道，休美万物之性命，是好生恶杀之义也。</p><p>「初九无交害匪咎，艰则无咎」者，处大有之初，不能履中谦柔，必至骄盈陵物，故戒之：即日虽无交切之害，后必将至，若欲免其凶咎，当须艰固不盈，即得「无咎」也。</p><p>「九二，大车以载，有攸往，无咎」者，以刚居中而应于五，为君委任，即是持正之臣，任重专权，犹如大车，所载非少，体既刚强，不惧倾败，谓车材强壮，以斯而往，何咎之有？故曰「大车以载，有攸往，无咎」也。</p><p>「九三，公用亨于天子，小人弗克」者，公谓臣之贵极也；九三以刚健盛极，权臣之象也。若以贤良处之，即得亨于天子，助化之道也；若以小人处之，祸害立至，故曰「小人弗克」也。</p><p>「九四，匪其彭，无咎」者，彭，旁也，谓去三之旁而从于君也。九四逼近九三，三是权臣，威权之盛，所以九四欲舍九五而从九三，舍君事臣，违于常理。若能弃三旁而归于五，即得「无咎」也。</p><p>六五，厥孚交如，威如，吉者，以柔处尊，志又弘大，体柔即和顺于物，居中即所纳不遗，群贤悉归，信接于下，故不言之化而教自行，不令之威而人皆服，自然获吉，何难何防？任之得人，故易而无备矣。</p><p>上九「自天祐之，吉，无不利」者，居「大有」之时而不履位，尚贤也。余皆乘刚，而上九独乘柔，顺思顺也。五有信德而亲比焉，是履信也。有此三德，故从天以下皆祐助之而得其吉，无所不利也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
